SELECT pt.id, pt.account_id, pt.receipt_id, pt.amount, pt.type, pt.transaction_date, pt.description, pt.create_time, pa.name as account_name, CAST(r.id AS CHAR) as receipt_number FROM payment_transaction pt LEFT JOIN payment_account pa ON pt.account_id = pa.id LEFT JOIN receipts r ON pt.receipt_id = r.id WHERE 1=1
AND pt.account_id = #{accountId}
AND pt.receipt_id = #{receiptId}
AND pt.type = #{type}
AND pt.transaction_date BETWEEN #{startDate} AND #{endDate}
AND pt.description LIKE CONCAT('%', #{description}, '%')
ORDER BY pt.transaction_date DESC

SELECT SUM(CASE WHEN type = 'income' THEN amount ELSE 0.0 END) as total_income, SUM(CASE WHEN type = 'expense' THEN amount ELSE 0.0 END) as total_expense, SUM(CASE WHEN type = 'income' THEN amount ELSE -amount END) as net_amount FROM payment_transaction WHERE 1=1
AND account_id = #{accountId}
AND transaction_date BETWEEN #{startDate} AND #{endDate}

SELECT
pt.id, pt.account_id, pt.receipt_id, pt.amount, pt.type, pt.transaction_date, pt.description, pt.create_time,
pa.name as account_name,
CAST(r.id AS CHAR) as receipt_number
FROM payment_transaction pt
LEFT JOIN payment_account pa ON pt.account_id = pa.id
LEFT JOIN receipts r ON pt.receipt_id = r.id
WHERE 1=1



